    // Compute M^t
    const Mt = matrixPower(M, t, n);

    // Multiply Mt * state
    const finalState = new Array(6).fill(0);
    for (let i = 0; i < 6; i++) {
        for (let j = 0; j < 6; j++) {
            finalState[i] = (finalState[i] + Mt[i][j] * state[j]) % n;
        }
        finalState[i] = mod(finalState[i], n);
    }

    const Xt = finalState[0];
    const Yt = finalState[1];

    const ansX = Xt + 1;
    const ansY = Yt + 1;

    console.log(`${ansX} ${ansY}`);
});
